# -*- coding: utf-8 -*-
# Новые задачи 10 класса для навыков с < 3 подходящими задачами, 26.09.
from sympy import *
x, y = symbols("x y", real=True)
R = Rational
G = []
def T(skill, diff, atype, q, k, ds, check, vals=None):
    G.append(dict(skill=skill, diff=diff, atype=atype, q=q, k=k, ds=ds, check=check, vals=vals))
f = lambda e, v: e.subs(x, v)

# S01_03 таблица значений
T("G10_S01_03", "A", "text", r"Функция задана формулой $f(x) = x^{2} - 3x$. Найдите значения функции при $x = -1$, $x = 0$ и $x = 2$ (в этом порядке).",
  r"$4$; $0$; $-2$", [(r"$2$; $0$; $-2$", "Ученик вычислил (−1)² как −1: −1 + 3 = 2."),
                     (r"$4$; $0$; $10$", "Ученик ошибся в знаке при x = 2: сложил 4 и 6 вместо вычитания."),
                     (r"$-4$; $0$; $-2$", "Ученик потерял знак при подстановке x = −1: −3 · (−1) = +3.")],
  lambda: [f(x**2 - 3 * x, v) for v in (-1, 0, 2)] == [4, 0, -2])
T("G10_S01_03", "B", "text", r"Функция задана формулой $g(x) = 2^{x}$. Найдите значения функции при $x = -2$, $x = 0$ и $x = 3$ (в этом порядке).",
  r"$\dfrac{1}{4}$; $1$; $8$", [(r"$-4$; $1$; $8$", "Ученик заменил возведение в степень умножением при x = −2."),
                               (r"$\dfrac{1}{4}$; $0$; $8$", "Ученик считал, что 2⁰ = 0, а любое ненулевое число в нулевой степени равно 1."),
                               (r"$\dfrac{1}{4}$; $1$; $6$", "Ученик заменил возведение в степень умножением при x = 3.")],
  lambda: [2**Integer(v) for v in (-2, 0, 3)] == [R(1, 4), 1, 8])
# S01_02 вертикальный тест
T("G10_S01_02", "A", "text", r"Какое из множеств точек задаёт функцию $y = f(x)$?", r"$\{(1; 2),\ (2; 3),\ (3; 2)\}$",
  [(r"$\{(1; 2),\ (1; 3),\ (2; 4)\}$", "Ученик не заметил, что значению x = 1 соответствуют два значения y."),
   (r"$\{(2; 1),\ (2; 5)\}$", "Ученик не заметил, что значению x = 2 соответствуют два значения y."),
   (r"$\{(0; 0),\ (0; 1),\ (1; 1)\}$", "Ученик не заметил, что значению x = 0 соответствуют два значения y.")],
  lambda: len({p for p, _ in [(1, 2), (2, 3), (3, 2)]}) == 3)
T("G10_S01_02", "B", "text", r"Является ли окружность $x^{2} + y^{2} = 4$ графиком некоторой функции $y = f(x)$?", "нет",
  [("да", "Ученик не применил вертикальный тест: прямая x = 1 пересекает окружность в двух точках.")],
  lambda: len(solve(Eq(1 + y**2, 4), y)) == 2)
T("G10_S01_02", "A", "text", r"Какая из линий не является графиком функции $y = f(x)$?", r"прямая $x = 3$",
  [(r"прямая $y = 3$", "Ученик перепутал вертикальную прямую с горизонтальной: y = 3 — график постоянной функции."),
   (r"парабола $y = x^{2}$", "Ученик не применил вертикальный тест: любая вертикальная прямая пересекает параболу y = x² ровно в одной точке."),
   (r"график $y = |x|$", "Ученик не применил вертикальный тест: любая вертикальная прямая пересекает график y = |x| ровно в одной точке.")], lambda: True)
# S04_03 D(f(g(x)))
T("G10_S04_03", "A", "text", r"Даны функции $f(x) = \sqrt{x}$ и $g(x) = x - 5$. Найдите область определения функции $f(g(x))$.", r"$[5; +\infty)$",
  [(r"$[0; +\infty)$", "Ученик указал область определения внешней функции f, а не сложной функции."), (r"$(5; +\infty)$", "Ученик исключил x = 5, хотя √0 определён."),
   (r"$(-\infty; 5]$", "Ученик ошибся в знаке при решении неравенства x − 5 ≥ 0.")],
  lambda: solve_univariate_inequality(x - 5 >= 0, x, relational=False) == Interval(5, oo))
T("G10_S04_03", "B", "text", r"Даны функции $f(x) = \dfrac{1}{x}$ и $g(x) = x^{2} - 4$. Найдите область определения функции $f(g(x))$.", r"$x \neq \pm 2$",
  [(r"$x \neq 2$", "Ученик потерял корень x = −2 уравнения x² − 4 = 0."), (r"$x \neq 0$", "Ученик указал ограничение внешней функции для x, а не для g(x)."),
   (r"$x \neq 4$", "Ученик приравнял нулю x², а не x² − 4, и перепутал знак.")], lambda: set(solve(x**2 - 4, x)) == {2, -2})
# S06_10 корневые функции
T("G10_S06_10", "A", "text", r"Как из графика функции $y = \sqrt{x}$ получить график функции $y = \sqrt{x - 3} + 2$?", "сдвинуть на $3$ единицы вправо и на $2$ единицы вверх",
  [("сдвинуть на $3$ единицы влево и на $2$ единицы вверх", "Ученик ошибся в направлении горизонтального сдвига: f(x − 3) — сдвиг вправо."),
   ("сдвинуть на $3$ единицы вправо и на $2$ единицы вниз", "Ученик ошибся в направлении вертикального сдвига: + 2 — сдвиг вверх."),
   ("сдвинуть на $2$ единицы вправо и на $3$ единицы вверх", "Ученик перепутал горизонтальный и вертикальный сдвиги.")], lambda: True)
T("G10_S06_10", "B", "text", r"Найдите множество значений функции $y = \sqrt{x - 3} + 2$.", r"$[2; +\infty)$",
  [(r"$[3; +\infty)$", "Ученик указал область определения вместо множества значений."), (r"$[0; +\infty)$", "Ученик указал множество значений функции y = √x, не учтя сдвиг вверх на 2."),
   (r"$[-2; +\infty)$", "Ученик ошибся в направлении вертикального сдвига.")], lambda: minimum(sqrt(x - 3) + 2, x, Interval(3, oo)) == 2)
# S07_02 умножение на общий знаменатель
T("G10_S07_02", "A", "exact_number", r"Решите уравнение $\dfrac{x}{2} + \dfrac{x}{3} = 5$.", r"$6$",
  [(r"$25$", "Ученик сложил дроби как x/5, сложив знаменатели."), (r"$1$", "Ученик умножил на общий знаменатель 6 только левую часть: 3x + 2x = 5."),
   (r"$36$", "Ученик умножил на 6 только правую часть: получил 5x/6 = 30.")],
  lambda: solve(x / 2 + x / 3 - 5, x) == [6], vals=[6, 25, 1, 36])
T("G10_S07_02", "B", "exact_number", r"Решите уравнение $\dfrac{x + 1}{2} - \dfrac{x - 1}{3} = 2$.", r"$7$",
  [(r"$11$", "Ученик после умножения на 6 не сменил знак у второго слагаемого: −2(x − 1) = −2x + 2."),
   (r"$-3$", "Ученик умножил на общий знаменатель только левую часть уравнения."),
   (r"$9$", "Ученик потерял слагаемое +2 при раскрытии скобок −2(x − 1).")], lambda: solve((x + 1) / 2 - (x - 1) / 3 - 2, x) == [7])
# S12_04 переход к модулю
T("G10_S12_04", "A", "text", r"Решите уравнение $\sqrt{x^{2}} = 3$.", r"$x = \pm 3$",
  [(r"$x = 3$", "Ученик заменил √(x²) на x вместо |x| и потерял корень x = −3."), (r"$x = 9$", "Ученик возвёл в квадрат только правую часть."),
   (r"$x = \pm 9$", "Ученик возвёл 3 в квадрат, хотя √(x²) = |x| = 3.")], lambda: set(solve(sqrt(x**2) - 3, x)) == {3, -3})
T("G10_S12_04", "B", "text", r"Решите систему уравнений $$\begin{cases} \sqrt{x^{2}} = 3, \\ y + x = 5. \end{cases}$$", r"$(3; 2)$, $(-3; 8)$",
  [(r"$(3; 2)$", "Ученик заменил √(x²) на x и потерял решение x = −3."), (r"$(3; 2)$, $(-3; 2)$", "Ученик нашёл оба значения x, но не пересчитал y для x = −3."),
   (r"$(9; -4)$", "Ученик возвёл 3 в квадрат, решая √(x²) = 3.")],
  lambda: set(tuple(s) for s in solve([sqrt(x**2) - 3, y + x - 5], [x, y])) == {(3, 2), (-3, 8)})
T("G10_S12_04", "C", "expression", r"Упростите выражение $\sqrt{(x - 2)^{2}}$ при $x < 2$.", r"$2 - x$",
  [(r"$x - 2$", "Ученик заменил √((x − 2)²) на x − 2, не учтя, что при x < 2 это выражение отрицательно."),
   (r"$|x| - 2$", "Ученик перенёс модуль только на переменную."), (r"$-x - 2$", "Ученик ошибся в знаке при раскрытии модуля.")],
  lambda: simplify(sqrt((x - 2)**2).subs(x, -5) - (2 - x).subs(x, -5)) == 0 and simplify(sqrt((x - 2)**2).subs(x, 1) - 1) == 0,
  vals=[2 - x, x - 2, Abs(x) - 2, -x - 2])
# S23_06 arcsin x + arccos x
T("G10_S23_06", "A", "expression", r"Вычислите $\arcsin\dfrac{1}{3} + \arccos\dfrac{1}{3}$.", r"$\dfrac{\pi}{2}$",
  [(r"$\pi$", "Ученик перепутал тождество arcsin x + arccos x = π/2 с тождеством arccos x + arccos(−x) = π."),
   (r"$0$", "Ученик решил, что арксинус и арккосинус одного числа взаимно уничтожаются."), (r"$\dfrac{2}{3}$", "Ученик сложил аргументы вместо значений функций.")],
  lambda: abs(N(asin(R(1, 3)) + acos(R(1, 3)) - pi / 2, 30)) < 1e-25, vals=[pi / 2, pi, 0, R(2, 3)])
T("G10_S23_06", "B", "expression", r"Вычислите $\arcsin(-0{,}4) + \arccos(-0{,}4)$.", r"$\dfrac{\pi}{2}$",
  [(r"$0$", "Ученик решил, что из-за отрицательного аргумента сумма обращается в нуль."), (r"$-\dfrac{\pi}{2}$", "Ученик вынес знак минус из суммы, хотя тождество верно при любом x из [−1; 1]."),
   (r"$\pi$", "Ученик перепутал тождество с формулой arccos(−x) = π − arccos x.")],
  lambda: abs(N(asin(R(-2, 5)) + acos(R(-2, 5)) - pi / 2, 30)) < 1e-25, vals=[pi / 2, 0, -pi / 2, pi])
T("G10_S23_06", "C", "expression", r"Решите уравнение $\arcsin x = \arccos x$.", r"$x = \dfrac{\sqrt{2}}{2}$",
  [(r"$x = \pm\dfrac{\sqrt{2}}{2}$", "Ученик не проверил корень x = −√2/2: arcsin(−√2/2) = −π/4, а arccos(−√2/2) = 3π/4."),
   (r"$x = \dfrac{1}{2}$", "Ученик ошибся: arcsin(1/2) = π/6, arccos(1/2) = π/3."), (r"$x = 0$", "Ученик ошибся: arcsin 0 = 0, arccos 0 = π/2.")],
  lambda: simplify(asin(sqrt(2) / 2) - acos(sqrt(2) / 2)) == 0 and simplify(asin(-sqrt(2) / 2) - acos(-sqrt(2) / 2)) != 0, vals=[sqrt(2) / 2, R(1, 2), 0])
# S08_03 метод сложения
T("G10_S08_03", "A", "text", r"Решите систему уравнений способом сложения: $$\begin{cases} x + y = 7, \\ x - y = 1. \end{cases}$$", r"$(4; 3)$",
  [(r"$(3; 4)$", "Ученик перепутал значения x и y."), (r"$(4; -3)$", "Ученик ошибся в знаке при нахождении y из x + y = 7."),
   (r"$(8; 6)$", "Ученик сложил уравнения, но не разделил 2x = 8 на 2.")], lambda: solve([x + y - 7, x - y - 1], [x, y]) == {x: 4, y: 3})
# S13_03 чтение графика показательной функции
T("G10_S13_03", "A", "exact_number", r"График функции $y = a^{x}$ проходит через точку $(2; 9)$. Найдите $a$.", r"$3$",
  [(r"$\dfrac{9}{2}$", "Ученик разделил 9 на 2 вместо извлечения квадратного корня."), (r"$-3$", "Ученик не учёл, что основание показательной функции положительно."),
   (r"$81$", "Ученик возвёл 9 в квадрат вместо извлечения корня.")],
  lambda: [s for s in solve(y**2 - 9, y) if s > 0] == [3], vals=[3, R(9, 2), -3, 81])
T("G10_S13_03", "B", "exact_number", r"График функции $y = a^{x}$ проходит через точку $\left(-1; \dfrac{1}{4}\right)$. Найдите $a$.", r"$4$",
  [(r"$\dfrac{1}{4}$", "Ученик не учёл, что показатель отрицательный: a⁻¹ = 1/4 означает a = 4."), (r"$-4$", "Ученик ошибся в знаке основания."),
   (r"$2$", "Ученик извлёк квадратный корень из 4.")], lambda: solve(1 / y - R(1, 4), y) == [4], vals=[4, R(1, 4), -4, 2])
T("G10_S13_03", "C", "exact_number", r"Показательная функция $y = a^{x}$ убывает, а её график проходит через точку $(-2; 16)$. Найдите $a$.", r"$\dfrac{1}{4}$",
  [(r"$4$", "Ученик решил уравнение a² = 16 вместо a⁻² = 16."), (r"$-\dfrac{1}{4}$", "Ученик не учёл, что основание показательной функции положительно."),
   (r"$\dfrac{1}{16}$", "Ученик не извлёк квадратный корень.")], lambda: [s for s in solve(y**-2 - 16, y) if s > 0] == [R(1, 4)], vals=[R(1, 4), 4, -R(1, 4), R(1, 16)])
# S23_03 отрицательный аргумент
T("G10_S23_03", "A", "expression", r"Вычислите $\arccos\left(-\dfrac{1}{2}\right)$.", r"$\dfrac{2\pi}{3}$",
  [(r"$-\dfrac{\pi}{3}$", "Ученик применил к арккосинусу свойство арксинуса: arccos(−x) = π − arccos x, а не −arccos x."),
   (r"$\dfrac{\pi}{3}$", "Ученик потерял знак минус у аргумента."), (r"$-\dfrac{2\pi}{3}$", "Ученик взял значение вне области значений арккосинуса [0; π].")],
  lambda: acos(-R(1, 2)) == 2 * pi / 3, vals=[2 * pi / 3, -pi / 3, pi / 3, -2 * pi / 3])
# S06_04 растяжение
T("G10_S06_04", "A", "text", r"Как получить график функции $y = 2f(x)$ из графика функции $y = f(x)$?", r"растяжением от оси $Ox$ в $2$ раза",
  [(r"сжатием к оси $Ox$ в $2$ раза", "Ученик перепутал растяжение со сжатием: множитель 2 > 1 растягивает график."),
   (r"растяжением от оси $Oy$ в $2$ раза", "Ученик перепутал преобразование y = 2f(x) с преобразованием y = f(x/2)."),
   (r"сдвигом вверх на $2$ единицы", "Ученик перепутал умножение функции на 2 с прибавлением 2.")], lambda: True)
# S06_05 сжатие
T("G10_S06_05", "B", "text", r"Точка $(4; 5)$ лежит на графике функции $y = f(x)$. Какая точка обязательно лежит на графике функции $y = f(2x)$?", r"$(2; 5)$",
  [(r"$(8; 5)$", "Ученик умножил абсциссу на 2, а при y = f(2x) она делится на 2."), (r"$(4; 10)$", "Ученик перепутал y = f(2x) с y = 2f(x)."),
   (r"$(2; 10)$", "Ученик изменил обе координаты.")], lambda: 2 * 2 == 4)
# S06_07 отражение относительно Oy
T("G10_S06_07", "A", "text", r"Точка $(3; -2)$ лежит на графике функции $y = f(x)$. Какая точка обязательно лежит на графике функции $y = f(-x)$?", r"$(-3; -2)$",
  [(r"$(3; 2)$", "Ученик выполнил отражение относительно оси Ox, а не Oy."), (r"$(-3; 2)$", "Ученик сменил знаки обеих координат (симметрия относительно начала координат)."),
   (r"$(-2; 3)$", "Ученик поменял координаты местами.")], lambda: True)
# S06_09 определение преобразования
T("G10_S06_09", "A", "expression", r"График функции $g$ получен из графика функции $f(x) = x^{2}$ сдвигом на $4$ единицы вправо. Задайте функцию $g$ формулой.", r"$g(x) = (x - 4)^{2}$",
  [(r"$g(x) = (x + 4)^{2}$", "Ученик ошибся в направлении сдвига: сдвиг вправо — это f(x − 4)."), (r"$g(x) = x^{2} - 4$", "Ученик выполнил сдвиг вниз вместо сдвига вправо."),
   (r"$g(x) = x^{2} + 4$", "Ученик выполнил сдвиг вверх вместо сдвига вправо.")], lambda: True)
T("G10_S06_09", "B", "expression", r"График функции $g$ получен из графика функции $f(x) = |x|$ отражением относительно оси $Ox$ и последующим сдвигом вверх на $1$. Задайте функцию $g$ формулой.",
  r"$g(x) = -|x| + 1$", [(r"$g(x) = -|x + 1|$", "Ученик выполнил сдвиг влево вместо сдвига вверх."), (r"$g(x) = |x| + 1$", "Ученик выполнил отражение относительно оси Oy, которое не меняет график |x|."),
                        (r"$g(x) = -|x| - 1$", "Ученик ошибся в направлении вертикального сдвига.")], lambda: True)
T("G10_S06_09", "C", "text", r"С помощью каких преобразований график функции $g(x) = \sqrt{-x} + 3$ получается из графика функции $f(x) = \sqrt{x}$?",
  r"отражением относительно оси $Oy$ и сдвигом вверх на $3$", [(r"отражением относительно оси $Ox$ и сдвигом вверх на $3$", "Ученик перепутал f(−x) и −f(x)."),
                                                          (r"сдвигом влево на $3$", "Ученик принял слагаемое +3 за горизонтальный сдвиг."),
                                                          (r"отражением относительно оси $Oy$ и сдвигом вправо на $3$", "Ученик принял слагаемое +3 за горизонтальный сдвиг.")], lambda: True)
